class Resource extends Base {
 mount(){this.render(`<section class="scene"><header><span class="label">TYPE IS A MATERIAL</span><span class="edition">MOTION STUDY / 04</span></header><h2></h2><div class="baseline"></div><footer><p>Words arrive differently<br>when you give them room.</p><button class="secondary" data-replay>Replay sequence ↗</button></footer></section>`,`.scene{background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);min-height:485px;padding:30px;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden}header,footer{display:flex;align-items:center;justify-content:space-between;gap:20px}.edition{font-size:8px;color:var(--muted);letter-spacing:1px}h2{font:500 clamp(39px,7vw,77px)/1.03 Georgia,serif;letter-spacing:-3px;max-width:650px;margin:38px 0;display:flex;flex-wrap:wrap;column-gap:.21em;row-gap:.02em}.word-mask{display:inline-block;overflow:hidden;padding-bottom:.12em;margin-bottom:-.12em}.word{display:block;color:var(--ink)}.word-mask:nth-child(3n) .word{font-style:italic;color:var(--accent)}.baseline{height:1px;background:var(--line)}footer{padding-top:24px}footer p{font-size:11px;line-height:1.7;color:var(--muted)}footer button{font-size:11px;white-space:nowrap}@media(max-width:480px){.scene{padding:24px 20px}h2{letter-spacing:-2px}.edition{display:none}}`);this.listen(this.$('[data-replay]'),'click',()=>this.replay());this.buildText();}
 buildText(){const text=this.text('text','Make room for the unexpected.').slice(0,180);this.$('h2').setAttribute('aria-label',text);this.$('h2').innerHTML=text.split(/\s+/).map(word=>`<span class="word-mask" aria-hidden="true"><span class="word">${escape(word)}</span></span>`).join('');this.replay();}
 configured(name){if(name==='text')this.buildText();if(name==='speed')this.replay();}
 replay(){this.$$('.word').forEach((node,i)=>{node.getAnimations().forEach(a=>a.cancel());const animation=this.tween(node,[{transform:'translateY(112%) rotate(4deg)',opacity:.15},{transform:'translateY(0) rotate(0)',opacity:1}],{duration:850/this.number('speed',1,.4,2),delay:i*90/this.number('speed',1,.4,2),fill:'both'});if(i===this.$$('.word').length-1&&animation)animation.onfinish=()=>this.emit('reveal-complete',{text:this.text('text','Make room for the unexpected.')});});}
}
